#nullable enable // autogenerated

using MVZ2.Vanilla.Entities;
using MVZ2.Vanilla.Properties;
using PVZEngine;
using PVZEngine.Entities;
using PVZEngine.Level;
using PVZEngine.Modifiers;
using Tools;
using UnityEngine;

namespace MVZ2.GameContent.Effects
{
    [EntityBehaviourDefinition(VanillaEffectNames.pagodaLaserChaos)]
    public class PagodaLaserChaos : EffectBehaviour
    {
        public PagodaLaserChaos(string nsp, string name) : base(nsp, name)
        {
            AddModifier(new Vector3Modifier(EngineEntityProps.DISPLAY_SCALE, NumberOperator.Multiply, PROP_SCALE_MULTIPLIER));
        }
        public override void Init(Entity entity)
        {
            base.Init(entity);
            entity.SetProperty(PROP_TIMER, new FrameTimer(15));
        }
        public override void Update(Entity entity)
        {
            base.Update(entity);
            UpdateModel(entity);
        }
        private void UpdateModel(Entity entity)
        {
            var parent = entity.Parent;
            if (parent.ExistsAndAlive())
            {
                entity.Position = parent.Position + PagodaLaser.POSITION_OFFSET;
            }
            var timer = entity.GetProperty<FrameTimer>(PROP_TIMER);
            if (timer == null || timer.Expired)
            {
                entity.SetProperty(PROP_SCALE_MULTIPLIER, Vector3.zero);
                entity.Remove();
            }
            else
            {
                timer.Run();
                var scaleMultiplier = Vector3.one * timer.GetTimeoutPercentage();
                entity.SetProperty(PROP_SCALE_MULTIPLIER, scaleMultiplier);
            }
        }
        public static readonly VanillaEntityPropertyMeta<FrameTimer> PROP_TIMER = new VanillaEntityPropertyMeta<FrameTimer>("timer");
        public static readonly VanillaEntityPropertyMeta<Vector3> PROP_SCALE_MULTIPLIER = new VanillaEntityPropertyMeta<Vector3>("scale_multiplier", Vector3.one);
    }
}